def analyze_message_patterns():
    messages = load_messages()
    common_diffs = []
    for msg in messages:
        if len(msg) == 9:  # 3-letter patterns
            diffs = [msg[i] - msg[i-1] for i in range(1, len(msg))]
            common_diffs.append(diffs)
    return common_diffs

def calculate_gcd_sequence(sequence):
    """Calculate GCD of differences in sequence"""
    diffs = [abs(b - a) for a, b in zip(sequence[:-1], sequence[1:])]
    if not diffs:
        return None
    result = abs(diffs[0])
    for d in diffs[1:]:
        result = gmpy2.gcd(result, abs(d))
    return int(result)

def get_matrix_properties(x, y):
    """Get important properties of the matrix"""
    matrix = sage.Matrix([[3, 6, x], 
                         [y, 4, 2], 
                         [1, 5, 7]])
    try:
        det = matrix.det()
        eigenvals = matrix.eigenvalues()
        trace = matrix.trace()
        return det, eigenvals, trace
    except:
        return None, None, None

def try_matrix_with_server(x, y):
    """Try matrix values with the server"""
    try:
        conn = remote('crypto.chal.csaw.io', 5000)
