def check_known_encrypted_word(x, y, word, target_output):
    """Check if encrypting a known word gives expected output"""
    matrix = [3, 6, x, y, 4, 2, 1, 5, 7]
    ecm = M(3, 3)
    ecm.populate(matrix)
    e = Enc(ecm, word)
    result = e.encrypt()

    # Allow some variance in the output
    total_diff = sum(abs(a - b) for a, b in zip(result, target_output))
    return total_diff < 50  # Threshold for similarity

def find_matrix_advanced():
    """Find the correct matrix values using advanced mathematical analysis"""
    patterns = analyze_message_patterns()
    common_gcds = set()
    for pattern in patterns:
        gcd = calculate_gcd_sequence(pattern)
        if gcd:
            common_gcds.add(gcd)

    most_common_gcd = max(common_gcds, key=lambda x: sum(1 for g in common_gcds if g % x == 0))

    # Known messages from messages.txt for verification
    known_messages = load_messages()
    three_letter_msgs = [msg for msg in known_messages if len(msg) == 9]

    # Try values that preserve matrix properties
    for x in range(-15, 16):
        for y in range(-15, 16):
            det, eigenvals, trace = get_matrix_properties(x, y)

            if det is None or abs(det) < 0.001:
                continue

            # Check if determinant is related to common GCD
            if abs(det) % most_common_gcd != 0:
                continue

            # Test against known patterns
            matches = 0
            for pattern in three_letter_msgs[:3]:  # Test first few patterns
                if check_known_encrypted_word(x, y, "aaa", pattern):
                    matches += 1
                if check_known_encrypted_word(x, y, "abc", pattern):
                    matches += 1

            if matches >= 2:
                print(f"Testing promising values: x={x}, y={y}")
                success, response = try_matrix_with_server(x, y)
                if success:
                    return x, y, response

    return None

print("Starting advanced matrix solver...")
result = find_matrix_advanced()

if result:
    x, y, flag = result
    print("\nSuccess! Found working matrix:")
    print(f"x={x}, y={y}")
    print(f"Flag: {flag}")
else:
