#!/usr/bin/env python3
import string
import dataclasses
import typing as t
from itertools import product
import numpy as np
from pwn import *

# Original code from encoder.py
chars = list(" " + string.ascii_lowercase)
char_to_idx = {c: i for i, c in enumerate(chars)}
idx_to_char = {i: c for i, c in enumerate(chars)}

@dataclasses.dataclass
class E:
    row: int
    col: int
    val: int

@dataclasses.dataclass
class M:
    rows: int
    cols: int
    m: t.List[E] = dataclasses.field(default_factory=lambda: [])

    def populate(self, arr):
        self.m = [E(i, j, arr[self.cols * i + j])
                 for i in range(self.rows) for j in range(self.cols)
                 if (self.cols * i + j < len(arr))]

    def mul(self, other):
        if self.cols != other.rows:
            raise Exception()

        row, col = self.rows, other.cols
        new = M(row, col)
        new.m = [self.elem_mul(other, i, j)
                for i in range(new.rows) for j in range(new.cols)]
        return new

    def elem_mul(self, other, row, col):
        e = E(row, col, 0)
        s = 0
        for i in range(self.cols):
            s += self.m[self.cols * row + i].val * other.m[other.cols * i + col].val
        e.val = s
        return e

class Enc:
    def __init__(self, enc, m):
        self.enc = enc
        self.s = enc.rows
        self.m = [
            idx
            for c in m for idx in range(len(chars))
            if c == chars[idx]
        ]

    def encrypt(self):
        c = int(len(self.m) / self.s)
        encm = []
        for i in range(c):
            mc = self.m[i * self.s: (i * self.s) + self.s]
            mx = M(3, 1)
            mx.populate(mc)
            enc_mx = self.enc.mul(mx)
            for e in enc_mx.m:
                encm += [e.val]

        if (len(self.m) % 3 > 0):
            mc = self.m[c * self.s: (c * self.s) + self.s]
            for i in range(3 - len(mc)):
                mc.append(-1)
            mx = M(3, 1)
            mx.populate(mc)
            enc_mx = self.enc.mul(mx)
            for e in enc_mx.m:
                encm += [e.val]

        return encm

def encrypt_text(matrix, text):
    ecm = M(3, 3)
    ecm.populate(matrix)
    e = Enc(ecm, text)
    return e.encrypt()

def load_messages():
    with open('/home/ctfplayer/ctf_files/messages.txt', 'r') as f:
        return [eval(line.strip()) for line in f]

def check_pattern_match(output1, output2):
    if len(output1) != len(output2):
        return False
    differences = [abs(a - b) for a, b in zip(output1, output2)]
    return all(diff < 20 for diff in differences)  # Increased tolerance

def find_repeated_patterns(messages):
    # Group messages by length
    by_length = {}
    for msg in messages:
        l = len(msg)
        if l not in by_length:
            by_length[l] = []
        by_length[l].append(msg)

    # Find patterns in same-length messages
    patterns = []
    for length, msgs in by_length.items():
        if len(msgs) > 1:
            for i, msg1 in enumerate(msgs):
                for msg2 in msgs[i+1:]:
                    diffs = [b - a for a, b in zip(msg1, msg2)]
                    if len(set(diffs)) < len(diffs)/2:  # If many differences are the same
                        patterns.append((msg1, msg2, diffs))
    return patterns

def test_matrix_values(x, y, messages, patterns):
    matrix = [3, 6, x, y, 4, 2, 1, 5, 7]

    # Test cases that match message patterns
    test_cases = [
        'aaa', 'abc', 'the', 'and', 'ing',  # Common English patterns
        'flag', 'key', 'pass',  # Challenge-related words
        'xyz', 'zzz', '   '  # Edge cases
    ]

    matches = 0
    for test_case in test_cases:
        test_output = encrypt_text(matrix, test_case)

        # Check against real messages
        for msg in messages:
            if len(msg) == len(test_output) and check_pattern_match(test_output, msg):
                matches += 1

        # Check pattern differences
        if matches > 0:
            for pat1, pat2, diffs in patterns:
                test_out2 = encrypt_text(matrix, test_case + 'a')  # Test with variation
                if len(test_output) == len(pat1) and len(test_out2) == len(pat2):
                    test_diffs = [b - a for a, b in zip(test_output, test_out2)]
                    if any(abs(d1 - d2) < 20 for d1, d2 in zip(diffs, test_diffs)):
                        matches += 1

    return matches

def analyze_matrix_properties():
    messages = load_messages()
    patterns = find_repeated_patterns(messages)

    # Analyze message characteristics
    all_vals = [val for msg in messages for val in msg]
    mean_val = sum(all_vals) / len(all_vals)
    min_val = min(all_vals)
    max_val = max(all_vals)

    print(f"Message statistics:")
    print(f"Mean value: {mean_val:.2f}")
    print(f"Range: {min_val} to {max_val}")

    # Determine search ranges based on matrix properties
    # Using constraints from known matrix values: [3,6,x,y,4,2,1,5,7]
    # Known determinant properties and matrix characteristics
    x_min, x_max = -8, 8
    y_min, y_max = -8, 8

    best_matches = 0
    best_candidates = []

    total_combinations = (x_max - x_min + 1) * (y_max - y_min + 1)
    print(f"\nTesting {total_combinations} matrix combinations...")

    for x, y in product(range(x_min, x_max + 1), range(y_min, y_max + 1)):
        matches = test_matrix_values(x, y, messages, patterns)

        if matches > best_matches:
            best_matches = matches
            best_candidates = [(x, y)]
            print(f"New best: x={x}, y={y} with {matches} matches")
        elif matches == best_matches and matches > 0:
            best_candidates.append((x, y))

    return best_candidates

def try_matrix_with_server(x, y):
    try:
        conn = remote('crypto.chal.csaw.io', 5000)
        matrix = [3, 6, x, y, 4, 2, 1, 5, 7]
        matrix_str = ','.join(map(str, matrix))

        conn.recvuntil(b'matrix:')
        conn.sendline(matrix_str.encode())
        conn.sendline(b'flag')  # Send 'flag' as the message to encrypt

        response = conn.recvall(timeout=2).decode()
        if 'flag{' in response.lower():
            return True, response
        return False, response
    except Exception as e:
        return False, str(e)
    finally:
        try:
            conn.close()
        except:
            pass

def main():
    print("Starting analysis of the matrix system...")
    candidates = analyze_matrix_properties()

    if not candidates:
        print("No promising candidates found.")
        return

    print(f"\nTesting {len(candidates)} promising candidates with server...")
    for x, y in candidates:
        print(f"Testing matrix with x={x}, y={y}...")
        success, response = try_matrix_with_server(x, y)
        if success:
            print("Success! Found valid matrix values:")
            print(f"x={x}, y={y}")
            print(f"Server response: {response}")
            return
        elif 'incorrect' not in response.lower():
            print(f"Interesting response for x={x}, y={y}: {response}")

    print("No valid matrix found. Consider adjusting the search parameters.")

if __name__ == "__main__":
    main()
